style.css:
/* Fondo personalizado para Roblox */
html, body {
    background-color: #000000 !important; /* Fondo negro */
    background-image: url('https://example.com/sample_700e5f4a2a209b5a0a8fd12e87a2'); /* Reemplaza con la URL real */
    background-size: cover; /* La imagen cubrirá toda la pantalla */
    background-position: center center; /* Centra la imagen */
    background-repeat: no-repeat; /* Evita que la imagen se repita */
    color: white; /* El color del texto será blanco */
}

/* Opcional: Cambia el color de los enlaces para que resalten */
a {
    color: #00ff00; /* Un verde brillante */
}

/* Opcional: Cambia el color del texto en los botones */
button {
    background-color: #333333; /* Color de fondo del botón */
    color: white; /* Color de texto */
    border: 2px solid #00ff00; /* Borde verde */
}
